// 2. 조문 스키마 & 평가기
// ─────────────────────────────────────────────
/**
 * cond 지원 연산자
 *   투간:      [십성...]  — 모두 천간에 있어야
 *   투간_or:   [십성...]  — 하나 이상 천간에
 *   유:        [십성...]  — 천간/지지 어디든 모두
 *   유_or:     [십성...]
 *   무:        [십성...]  — 천간/지지 어디에도 없어야
 *   천간무:    [십성...]
 *   충월지:    true|false
 *   fn:        (ctx) => boolean
 */
function evalCond(cond, ctx, 유효만 = false) {
  const map = 유효만 ? (ctx.유효천간 ?? ctx.cheongan) : ctx.cheongan;
  const inGan = s => (map[s]?.length ?? 0) > 0;
  const inAny = s => inGan(s) || (ctx.jiji[s]?.length ?? 0) > 0;

  if (cond.투간     && !cond.투간.every(inGan))          return false;
  if (cond.투간_or  && !cond.투간_or.some(inGan))        return false;
  if (cond.투간_or2 && !cond.투간_or2.some(inGan))       return false;
  if (cond.유       && !cond.유.every(inAny))            return false;
  if (cond.유_or    && !cond.유_or.some(inAny))          return false;
  if (cond.무       && cond.무.some(inAny))              return false;
  if (cond.천간무   && cond.천간무.some(inGan))          return false;
  if (cond.합국    && !cond.합국.some(s => (ctx.합국?.[s]?.length ?? 0) > 0)) return false;
  if (cond.합국무  && cond.합국무.some(s => (ctx.합국?.[s]?.length ?? 0) > 0)) return false;
  if (cond.충월지 !== undefined && cond.충월지 !== ctx.chungWolji) return false;
  if (cond.fn       && !cond.fn(ctx))                     return false;
  return true;
}

// ─────────────────────────────────────────────
// 3. 조문 (자평진전 用神成敗救應)
// ─────────────────────────────────────────────
const 합거된 = (ctx, ss) => (ctx.합거 ?? []).some(x => x.십성 === ss);
const 금수상관 = ctx => ['庚','辛'].includes(ctx.ilGan) && ['亥','子','丑'].includes(ctx.wolJi);
const 재 = ['정재','편재'], 인 = ['정인','편인'], 식상 = ['식신','상관'], 비겁 = ['비견','겁재'];

/**
 * 몸의 무게 — 인수를 뺀 제 뿌리로만 잰다.
 * 論印 「必身重印輕，或身輕印重」은 身과 印을 따로 세는 말이므로,
 * 인수가 두터워 '신강'으로 잡히는 것을 身重으로 세면 「身輕印重」이 성립할 수 없다.
 * 茅狀元 己巳癸酉癸未庚申이 그 예 — 통근 0.25에 인수 2.5인데 신강으로 판정됐다.
 */
function 신중(c) { return (c.통근?.score ?? 0) + (c.sery.비겁 ?? 0) * 0.3 >= 1.0; }

/** 월령 지장간에 그 십성이 있으나 천간에 드러나지 않았는가 (暗官·藏煞) */
function 월령암장(c, 십성) {
  return JIJANGGAN[c.wolJi].some(x => sipseong(c.ilGan, x.gan) === 십성)
      && !(c.cheongan[십성]?.length);
}
/** 그 계열이 천간에 드러났는가 */
function 투출됨(c, 십성목록) {
  return 십성목록.some(x => (c.cheongan[x]?.length ?? 0) > 0);
}
/** 두 계열이 천간에서 인접해 있는가 (財印相並) */
/** 비일간 자리(년·월·시)에서의 인접 — 월-시는 일간을 건너 인접으로 본다(剋은 일간을 넘어 이른다) */
function 비일간인접(c, A목록, B목록) {
  const P = ['년','월','시'], 간 = { 년:c.yeonGan, 월:c.wolGan, 시:c.siGan };
  for (let i = 0; i < P.length - 1; i++) {
    const a = 간[P[i]], b = 간[P[i+1]];
    if (!a || !b) continue;
    const sa = sipseong(c.ilGan, a), sb = sipseong(c.ilGan, b);
    if ((A목록.includes(sa) && B목록.includes(sb)) || (B목록.includes(sa) && A목록.includes(sb))) return true;
  }
  return false;
}
/** 傷官見官이 실제로 성립하는가 — 27편 支干有別 + 13편 隔 */
function 상관이관을친다(c) {
  const 관투출 = (c.cheongan['정관']?.length ?? 0) > 0;
  if (관투출) return 비일간인접(c, ['상관'], ['정관']);
  // 관이 월지에 숨어 있으면, 그 바로 위 월간의 상관만 친다
  return c.wolGan && sipseong(c.ilGan, c.wolGan) === '상관';
}
function 인접함(c, A목록, B목록) {
  const P = ['년','월','일','시'], 간 = { 년:c.yeonGan, 월:c.wolGan, 일:c.ilGan, 시:c.siGan };
  for (let i = 0; i < P.length - 1; i++) {
    const a = 간[P[i]], b = 간[P[i+1]];
    if (!a || !b) continue;
    const sa = sipseong(c.ilGan, a), sb = sipseong(c.ilGan, b);
    if ((A목록.includes(sa) && B목록.includes(sb)) || (B목록.includes(sa) && A목록.includes(sb))) return true;
  }
  return false;
}
/** 三奇 — 정관이 재와 인 사이에 끼어 둘이 서로 상하지 않는 배치 */
function 관이재인사이(c) {
  const P = ['년','월','일','시'], 간 = { 년:c.yeonGan, 월:c.wolGan, 일:c.ilGan, 시:c.siGan };
  const at = (목록) => P.filter(p => 간[p] && p !== '일' && 목록.includes(sipseong(c.ilGan, 간[p])))
                        .map(p => P.indexOf(p));
  const g = at(['정관']), f = at(재), i = at(인);
  return g.some(x => f.some(a => i.some(b => (a < x && x < b) || (b < x && x < a))));
}
/** 財先煞後，食以間之 — 재가 앞, 칠살이 뒤, 그 사이에 식신이 낀 배치 */
function 재선살후_식간(c) {
  const P = ['년','월','일','시'], 간 = { 년:c.yeonGan, 월:c.wolGan, 일:c.ilGan, 시:c.siGan };
  const idx = (십성) => P.findIndex(p => 간[p] && p !== '일' && sipseong(c.ilGan, 간[p]) === 십성);
  const 재i = Math.min(...재.map(idx).filter(i => i >= 0));
  const 살i = idx('편관'), 식i = idx('식신');
  if (!isFinite(재i) || 살i < 0 || 식i < 0) return false;
  return 재i < 살i && 식i > 재i && 식i < 살i;
}
/** 사이에 글자가 끼어 서로 극하지 못하는가 — 吳榜眼 「庚與丙隔二戊而不相尅」 */
function 격리됨(c, A, B) {
  const P = ['년','월','일','시'], 간 = { 년:c.yeonGan, 월:c.wolGan, 일:c.ilGan, 시:c.siGan };
  const pa = P.find(p => 간[p] && sipseong(c.ilGan, 간[p]) === A);
  const pb = P.find(p => 간[p] && sipseong(c.ilGan, 간[p]) === B);
  if (!pa || !pb) return false;
  return Math.abs(P.indexOf(pa) - P.indexOf(pb)) >= 2;
}


