const 支成局 = (c, o) => o === '土' ? 支四庫(c) : (삼합[o].every(j => c.지지.includes(j)) || 방합[o].every(j => c.지지.includes(j)));   // 土局은 사고(辰戌丑未) 셋 이상
const 得地 = (c, g) => c.정기.includes(g) || c.지장.includes(g);        // 지지에 뿌리
const 有根 = 得地;
const 合去 = (c, g) => {                                              // g가 곁 천간과 합해 묶임(일간 낀 합은 제외)
  const 차례 = [m => m.yeonGan, m => m.wolGan, m => m.ilGan, m => m.siGan].map(f => f(c.m));
  for (let i = 0; i < 4; i++) if (차례[i] === g) {
    for (const j of [i - 1, i + 1]) if (j >= 0 && j < 4 && j !== 2 && 차례[j] === 간합[g]) return true;
  }
  return false;
};
const 比劫重重 = c => (오행透수(c, '土') + c.정기.filter(g => 오행[g] === '土').length) >= 2;   // 천간 세 자리로는 못 채우니 본기까지
const 無比印 = c => 오행透수(c, '土') === 0 && 오행透수(c, '火') === 0 && !c.정기.some(g => 오행[g] === '土' || 오행[g] === '火');
const 일간무근 = c => !c.지장.some(g => 오행[g] === '土');
const 官殺滿 = c => (오행透수(c, '木') + c.정기.filter(g => 오행[g] === '木').length) >= 3;
const 財滿 = c => (오행透수(c, '水') + c.정기.filter(g => 오행[g] === '水').length) >= 3;
const 傷 = (c, 극하는, 극당하는) => 透(c, 극하는) && 透(c, 극당하는);  // 둘 다 천간에 드러나 부딪힘(격리는 미구현)
const 有오행 = (c, o) => c.천간.some(g => 오행[g] === o) || c.정기.some(g => 오행[g] === o);
const 無오행 = (c, o) => !有오행(c, o);
const 透오행 = (c, o) => c.천간.some(g => 오행[g] === o);
const 支多 = (c, o) => c.정기.filter(g => 오행[g] === o).length >= 2;        // 지지 본기 둘 이상
const 多오행 = (c, o) => (오행透수(c, o) + c.정기.filter(g => 오행[g] === o).length) >= 3;
const 支見 = (c, ...js) => js.some(j => c.지지.includes(j));
const 支全 = (c, ...js) => js.every(j => c.지지.includes(j));
const 干全 = (c, ...gs) => gs.every(g => 透(c, g));
const 干皆 = (c, o) => c.천간.length >= 2 && c.천간.every(g => 오행[g] === o);   // 천간 전부 한 오행
const 比劫 = c => 오행透수(c, 오행[c.일간]);
const 무비겁 = c => 比劫(c) === 0 && !c.정기.some(g => 오행[g] === 오행[c.일간]);
const 無水 = c => 無오행(c, '水'), 無火 = c => 無오행(c, '火'), 無金 = c => 無오행(c, '金'), 無木 = c => 無오행(c, '木'), 無土 = c => 無오행(c, '土');
const 有水 = c => 有오행(c, '水'), 有火 = c => 有오행(c, '火'), 有金 = c => 有오행(c, '金'), 有木 = c => 有오행(c, '木'), 有土 = c => 有오행(c, '土');
const 時 = (c, g) => c.m.siGan === g, 時支 = (c, j) => c.m.siJi === j, 年 = (c, g) => c.m.yeonGan === g, 月干 = (c, g) => c.m.wolGan === g;
/** 조문 한 줄 만들기 */
const J = (id, 종류, 조건, 원문, 판정, 결, 월) => 월 ? { id, 종류, 조건, 원문, 판정, 결, 월 } : { id, 종류, 조건, 원문, 판정, 결 };

