const 판정어색인 = Object.entries(판정어).flatMap(([k, v]) => v.map(x => [x, k])).sort((a, b) => b[0].length - a[0].length);
const 방향찾기 = 말 => { for (const [x, k] of 판정어색인) if (말.includes(x)) return k; return null; };
